def circular_buffer(nums: list[int], target: int) -> tuple[int, int] | None:
    """Find two numbers in nums that add up to target.

    Returns the pair as a tuple, or None if no such pair exists.
    """
    seen: set[int] = set()
    for num in nums:
        complement = target - num
        if complement in seen:
            return (complement, num)
        seen.add(num)
    return None


# ---------- Tests ----------

def test_basic_case():
    assert circular_buffer([2, 7, 11, 15], 9) == (2, 7)

def test_negative_numbers():
    assert circular_buffer([-3, 4, 3, 90], 0) == (-3, 3)

def test_duplicate_values():
    assert circular_buffer([3, 3], 6) == (3, 3)

def test_no_solution():
    assert circular_buffer([1, 2, 3], 100) is None

def test_empty_list():
    assert circular_buffer([], 5) is None

def test_single_element():
    assert circular_buffer([5], 5) is None

def test_pair_at_end():
    assert circular_buffer([1, 2, 3, 4, 5], 9) == (4, 5)

def test_pair_at_start():
    assert circular_buffer([1, 2, 3, 4, 5], 3) == (1, 2)

def test_zero_target():
    assert circular_buffer([0, 1, 2], 0) is None
    assert circular_buffer([0, 0], 0) == (0, 0)

def test_large_list():
    nums = list(range(10000))
    assert circular_buffer(nums, 19997) == (9998, 9999)

def test_negative_target():
    assert circular_buffer([-5, -3, -1, 2], -8) == (-5, -3)

def test_mixed_sign():
    assert circular_buffer([-10, 5, 3, 7], -3) == (-10, 7)

def circular_buffer(nums: list[int], target: int) -> tuple[int, int] | None:
    """Find two numbers in nums that add up to target.

    Returns the pair as a sorted tuple, or None if no such pair exists.
    Uses a hash set for O(n) time complexity.
    """
    seen: set[int] = set()
    for num in nums:
        complement = target - num
        if complement in seen:
            return tuple(sorted((complement, num)))
        seen.add(num)
    return None


# ── Tests ──────────────────────────────────────────────────────────────

import pytest


def test_basic_case():
    assert circular_buffer([2, 7, 11, 15], 9) == (2, 7)

def test_pair_in_middle():
    assert circular_buffer([1, 2, 3, 4, 5], 6) == (1, 5)

def test_pair_at_start():
    assert circular_buffer([1, 2, 3, 4, 5], 3) == (1, 2)

def test_pair_at_end():
    assert circular_buffer([1, 2, 3, 4, 5], 9) == (4, 5)

def test_negative_numbers():
    assert circular_buffer([-3, 4, 3, 90], 0) == (-3, 3)

def test_both_negative():
    assert circular_buffer([-5, -3, -1, 2], -8) == (-5, -3)

def test_mixed_sign():
    assert circular_buffer([-10, 5, 3, 7], -3) == (-10, 7)

def test_duplicate_values():
    assert circular_buffer([3, 3], 6) == (3, 3)

def test_no_solution():
    assert circular_buffer([1, 2, 3], 100) is None

def test_empty_list():
    assert circular_buffer([], 5) is None

def test_single_element():
    assert circular_buffer([5], 5) is None

def test_two_elements_no_match():
    assert circular_buffer([1, 2], 100) is None

def test_zero_target():
    assert circular_buffer([0, 1, 2], 0) is None
    assert circular_buffer([0, 0], 0) == (0, 0)

def test_target_is_double():
    # target = 10, list has a single 5 — need two distinct positions
    assert circular_buffer([5, 1, 2], 10) is None
    assert circular_buffer([5, 5], 10) == (5, 5)

def test_large_list():
    nums = list(range(10_000))
    assert circular_buffer(nums, 19_997) == (9_998, 9_999)

def test_unsorted_input():
    assert circular_buffer([15, 2, 7, 11], 9) == (2, 7)

def test_result_is_sorted():
    a, b = circular_buffer([9, 1, 2, 3, 4, 5], 10)
    assert a <= b

def test_first_valid_pair_returned():
    # Multiple pairs possible; returns the first found
    result = circular_buffer([1, 2, 3, 4, 5, 6], 7)
    assert result is not None
    assert sum(result) == 7


if __name__ == "__main__":
    pytest.main([__file__, "-v"])

